<?php
namespace Core\Pan;require_once __DIR__.'/../Guard.php';ml_guard_shield(__FILE__);require_once __DIR__.'/BasePan.php';class Pan115Pan extends BasePan{public function __construct($a=array()){parent::__construct($a);$this->urlHeader=array('Accept: application/json, text/plain, */*','Accept-Language: zh-CN,zh;q=0.9','sec-ch-ua: "Chromium";v="122", "Not(A:Brand";v="24", "Google Chrome";v="122"','sec-ch-ua-mobile: ?0','sec-ch-ua-platform: "Windows"','sec-fetch-dest: empty','sec-fetch-mode: cors','sec-fetch-site: same-site','Referer: https://115cdn.com/','Referrer-Policy: strict-origin-when-cross-origin','user-agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36','cookie: '.$this->cfgVal('cookie'),);}public function transfer($a){if($this->passcode===''){return $this->err('请提供提取码（115 分享链接需带 ?password=）');}if(trim((string)$this->cfgVal('cookie',''))===''){return $this->err('115 未配置 Cookie（后台「站点设置 → 添加网盘」）');}if($this->isType===1){return $this->ok('检验成功',array('title'=>$this->getShareTitle($a),'share_url'=>$this->url,));}$b=$this->getShareInfo($a,$this->passcode);if($b['code']!==200){return $this->err(isset($b['message'])?$b['message']:'获取分享信息失败');}$c=isset($b['data']['pick_code'])?(string)$b['data']['pick_code']:'';if($c===''){return $this->err('获取分享信息失败');}$b=$this->transferToMyCloud($a,$c);if($b['code']!==200){return $this->err(isset($b['message'])?$b['message']:'转存失败');}$d=isset($b['data']['file_id'])?(string)$b['data']['file_id']:'';if($d===''){return $this->err('转存失败');}$b=$this->createShare($d);if($b['code']!==200){return $this->err(isset($b['message'])?$b['message']:'分享失败');}return $this->ok('转存成功',$b['data']);}private function getShareTitle($a){$b=$this->httpJson($this->withQuery('https://webapi.115.com/share/snap',array('share_code'=>$a,)),'GET',null,$this->urlHeader,20);if(is_array($b)&&isset($b['data']['file_name'])){return(string)$b['data']['file_name'];}return'未知文件';}private function getShareInfo($a,$b){$c=$this->httpJson($this->withQuery('https://webapi.115.com/share/sharinginfo',array('share_code'=>$a,'receive_code'=>$b,)),'GET',null,$this->urlHeader,20);if(is_array($c)&&isset($c['state'])&&$c['state']===true){return $this->ok('获取成功',isset($c['data'])&&is_array($c['data'])?$c['data']:array());}$d=is_array($c)&&isset($c['error_msg'])?(string)$c['error_msg']:'获取分享信息失败';return $this->err($d);}private function transferToMyCloud($a,$b){$c=$this->httpJson('https://webapi.115.com/share/sharelink','POST',http_build_query(array('share_code'=>$a,'pickcode'=>$b,)),$this->urlHeader,20);if(is_array($c)&&isset($c['state'])&&$c['state']===true){return $this->ok('转存成功',isset($c['data'])&&is_array($c['data'])?$c['data']:array());}$d=is_array($c)&&isset($c['error_msg'])?(string)$c['error_msg']:'转存失败';return $this->err($d);}private function createShare($a){$b=$this->getUserId();$c=$this->httpJson('https://webapi.115.com/share/send','POST',http_build_query(array('file_id'=>$a,'user_id'=>$b,)),$this->urlHeader,20);if(is_array($c)&&isset($c['state'])&&$c['state']===true){$d=isset($c['data']['share_code'])?(string)$c['data']['share_code']:'';return $this->ok('分享成功',array('title'=>isset($c['data']['file_name'])?(string)$c['data']['file_name']:'','share_url'=>'https://115cdn.com/s/'.$d,'fid'=>$a,));}$e=is_array($c)&&isset($c['error_msg'])?(string)$c['error_msg']:'分享失败';return $this->err($e);}private function getUserId(){$a=$this->httpJson('https://webapi.115.com/user/info','GET',null,$this->urlHeader,20);if(is_array($a)&&isset($a['data']['user_id'])){return(string)$a['data']['user_id'];}return'';}}